import pytest

from parse_dkt import parse_dkt


def test_full_form():
    assert parse_dkt("Dkt. No. 45-2 at 3:14-16") == {
        "entry": 45,
        "attachment": 2,
        "page": 3,
        "lines": [14, 16],
    }


def test_minimal_form():
    assert parse_dkt("Dkt. No. 45 at 3") == {
        "entry": 45,
        "attachment": None,
        "page": 3,
        "lines": None,
    }


def test_attachment_without_lines():
    assert parse_dkt("Dkt. No. 12-4 at 7") == {
        "entry": 12,
        "attachment": 4,
        "page": 7,
        "lines": None,
    }


def test_lines_without_attachment():
    assert parse_dkt("Dkt. No. 9 at 21:5-9") == {
        "entry": 9,
        "attachment": None,
        "page": 21,
        "lines": [5, 9],
    }


def test_reversed_line_range_raises():
    with pytest.raises(ValueError):
        parse_dkt("Dkt. No. 45-2 at 3:16-14")


def test_single_line_range_is_valid():
    assert parse_dkt("Dkt. No. 45 at 3:7-7")["lines"] == [7, 7]


def test_extra_whitespace_tolerated():
    assert parse_dkt("  Dkt.  No.   45 - 2   at   3 : 14 - 16  ") == {
        "entry": 45,
        "attachment": 2,
        "page": 3,
        "lines": [14, 16],
    }


def test_missing_page_raises():
    with pytest.raises(ValueError):
        parse_dkt("Dkt. No. 45-2")

